var union = a.Union(b);
var results = new[] { union, a.Intersect(b), a.Except(b), a.Union(b).Except(a.Intersect(b)) };
string[] labels = { "union", "intersection", "difference", "symmetric difference" };
for (int i = 0; i < labels.Length; i++)
    Console.WriteLine($"{labels[i]}: {string.Join(" ", results[i].Order())}");
